    "category": "Economia",
    "ingestedAt": "12/11/2026 às 14:24",
    "imageUrl": "https://imagens.ebc.com.br/xwr-J7PjAUAI5c-hV7wlc-bQ8zQ=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/09/08/j-0022-26-230726_-4-3.jpg?itok=z-7sr5ZN",
    "imageCaption": "Reúso de computadores pelo governo brasileiro gera economia de água",
